[asy]
unitsize(0.4 cm);

pair A, B, C, D;

A = (0,0);
B = (7,2);
D = (1,3);
C = B + D;

draw(A--B--C--D--cycle);
draw(A--C,dashed);
draw(B--D,dashed);

label("$A$", A, SW);
label("$B$", B, SE);
label("$C$", C, NE);
label("$D$", D, NW);

dot((A + C)/2);
[/asy]

